// Shared with Achille's website chat, so the app and the website behave
// alike. Generated by scripts/sync-shared.mjs: do not edit it here.

// Photos and files in the human-mode chat. The configuration's `attachments`
// object sets the limits (null or absent: no attach button, as for the Shop
// Assistant); the server enforces them again (422 too many, 413 too big).
// The type is not checked here: the server keeps anything outside its list as
// application/octet-stream (downloaded, never rendered).

export interface AttachmentLimits {
  maxFiles: number;
  maxFileBytes: number;
  maxTotalBytes: number;
  accept: string[];
}

export function parseAttachmentLimits(value: unknown): AttachmentLimits | null {
  if (!value || typeof value !== "object") return null;
  const { max_files, max_file_bytes, max_total_bytes, accept } = value as Record<string, unknown>;
  const counts = [max_files, max_file_bytes, max_total_bytes];
  if (!counts.every((n) => typeof n === "number" && Number.isFinite(n) && n > 0)) return null;
  if (!Array.isArray(accept) || !accept.every((type) => typeof type === "string")) return null;
  return {
    maxFiles: max_files as number,
    maxFileBytes: max_file_bytes as number,
    maxTotalBytes: max_total_bytes as number,
    accept: accept as string[],
  };
}

// The file input's accept attribute: the server's list, plus image/* so mobile
// pickers offer the camera.
export function inputAccept(limits: AttachmentLimits): string {
  const hasImages = limits.accept.some((type) => type.startsWith("image/"));
  return [...limits.accept, ...(hasImages ? ["image/*"] : [])].join(",");
}

export interface PickedFile {
  name: string;
  size: number;
  type: string;
}

export type FileProblem =
  | { kind: "too_many"; max: number }
  | { kind: "too_big"; name: string; max: number }
  | { kind: "total_too_big"; max: number };

// Adds the picked files to the selection, keeping the ones that fit and
// reporting the first that does not.
export function addFiles<T extends PickedFile>(
  current: readonly T[],
  incoming: readonly T[],
  limits: AttachmentLimits
): { files: T[]; problem: FileProblem | null } {
  const files = [...current];
  let problem: FileProblem | null = null;
  for (const file of incoming) {
    const issue = checkFile(file, files, limits);
    if (issue) problem ??= issue;
    else files.push(file);
  }
  return { files, problem };
}

function checkFile(file: PickedFile, selected: readonly PickedFile[], limits: AttachmentLimits): FileProblem | null {
  if (selected.length >= limits.maxFiles) return { kind: "too_many", max: limits.maxFiles };
  if (file.size > limits.maxFileBytes) return { kind: "too_big", name: file.name, max: limits.maxFileBytes };
  const total = selected.reduce((sum, f) => sum + f.size, file.size);
  if (total > limits.maxTotalBytes) return { kind: "total_too_big", max: limits.maxTotalBytes };
  return null;
}

// "840 Ko", "1,2 Mo" (units and decimal separator per locale).
export function formatFileSize(bytes: number, units: { kb: string; mb: string }, lang: string): string {
  if (bytes < 1024 * 1024) return `${Math.max(1, Math.round(bytes / 1024))} ${units.kb}`;
  const mb = new Intl.NumberFormat(lang, { maximumFractionDigits: 1 }).format(bytes / (1024 * 1024));
  return `${mb} ${units.mb}`;
}

// "{name} dépasse {size}." with the values filled in.
export function fillTemplate(template: string, values: Record<string, string | number>): string {
  return template.replace(/\{(\w+)\}/g, (match, key: string) => (key in values ? String(values[key]) : match));
}

// The message as multipart/form-data: the JSON body's fields, nested objects
// in bracket form (customer_identity[id], product_context[page_url]), plus
// files[]. Empty values are left out, as JSON.stringify leaves out undefined.
export function toFormData(payload: Record<string, unknown>, files: readonly Blob[]): FormData {
  const form = new FormData();
  for (const [key, value] of Object.entries(payload)) appendField(form, key, value);
  for (const file of files) form.append("files[]", file);
  return form;
}

function appendField(form: FormData, key: string, value: unknown) {
  if (value === undefined || value === null) return;
  if (typeof value === "object") {
    for (const [sub, subValue] of Object.entries(value as Record<string, unknown>)) {
      appendField(form, `${key}[${sub}]`, subValue);
    }
    return;
  }
  form.append(key, String(value));
}

export interface MessageAttachment {
  id: string;
  filename: string;
  content_type: string;
  size: number;
  // Short-lived signed URL; null on the optimistic copy of a message being sent.
  url: string | null;
}

// The poll's attachments, kept only when well formed; the URL only when it is
// http(s) (it becomes an href and an img src).
export function parseAttachments(value: unknown): MessageAttachment[] {
  if (!Array.isArray(value)) return [];
  return value.flatMap((item) => {
    if (!item || typeof item !== "object") return [];
    const { id, filename, content_type, size, url } = item as Record<string, unknown>;
    if (typeof id !== "string" || typeof filename !== "string") return [];
    return [{
      id,
      filename,
      content_type: typeof content_type === "string" ? content_type : "application/octet-stream",
      size: typeof size === "number" ? size : 0,
      url: typeof url === "string" && /^https?:\/\//i.test(url) ? url : null,
    }];
  });
}

// Thumbnails only for the image types every browser renders; a chip otherwise.
const THUMBNAIL_TYPES = ["image/jpeg", "image/png", "image/gif", "image/webp"];

export function isImageAttachment(attachment: MessageAttachment): boolean {
  return THUMBNAIL_TYPES.includes(attachment.content_type);
}
